    dimension: '载体', fieldHeight: '选择框高度', optionHeight: '选项行高', target: '最小热区', panel: '展开方式', app: '家电 App', tft: 'TFT 触控屏', narrow: '窄屏 / 小尺寸屏', remote: '旋钮 / 遥控器',
    appRule: '底部抽屉或锚定菜单；长列表优先全屏搜索', tftRule: '优先居中浮层或全屏列表，避免遮挡关键运行状态', narrowRule: '不使用悬浮下拉；切换到独立选择页或滚轮', remoteRule: '焦点进入列表后旋转/方向键移动，按压确认，返回取消',
    statesTitle: '状态', default: '默认', open: '展开', focus: '聚焦', disabled: '禁用', loading: '加载中', error: '错误', empty: '无结果', stateRule: '展开后高亮当前值；焦点态必须可由旋钮、遥控器和键盘识别。加载、空结果和错误应出现在列表区域，不让旧数据伪装成实时结果。',
    behaviorTitle: '交互规则', behaviorItems: ['单选时选中即提交并关闭；会改变运行中设备状态的选项，应在确认后再下发命令。','多选时保持面板打开，显示已选数量，并提供“完成”；不可把“全选”用于互斥或高风险项目。','列表打开后定位到当前值，不默认跳到第一项；禁用项保留可见并说明不可选原因。','支持点击外部、返回键或 Esc 关闭；关闭不应清除已经确认的值。','搜索无结果时保留用户输入，并提供清空或返回完整列表的路径。'],
