    appRule: 'Bottom sheet or anchored menu; use full-screen search for long lists', tftRule: 'Centered overlay or full-screen list; preserve critical running status', narrowRule: 'No floating dropdown; use a dedicated page or wheel', remoteRule: 'Rotate/arrows to move, press to confirm, Back to cancel',
